const screenNames={home:'Главная',operations:'Операции',learning:'Обучение Jarvis',analytics:'Аналитика',assistant:'AI-ассистент',goals:'Цели',sources:'Сбербанк и источники',settings:'Настройки'};
function setScreen(name,push=true){
 if(!Object.hasOwn(screenNames,name))name='home';currentScreen=name;
 for(const section of document.querySelectorAll('section[data-view]'))section.hidden=section.id!=='personal-cfo';
 for(const screen of document.querySelectorAll('[data-cfo-screen]'))screen.hidden=screen.dataset.cfoScreen!==name;
 for(const button of document.querySelectorAll('.sidebar button[data-nav]')){const selected=button.dataset.nav===name;button.classList.toggle('active',selected);if(selected)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current')}
 el('page-title').textContent=screenNames[name];if(push)history.pushState({},'','?screen='+name+'#home');window.scrollTo({top:0,behavior:'auto'});
 if(name==='learning')run(loadLearning);
}
function initializeScreens(){
 const root=el('personal-cfo'),pages={};const note=document.querySelector('.sidebar small');if(note)note.textContent='Банк — только чтение. Финансовые данные — локально.';
 for(const [name,label] of Object.entries(screenNames)){const section=node('div');section.dataset.cfoScreen=name;section.setAttribute('role','region');section.setAttribute('aria-label',label);section.hidden=true;root.append(section);pages[name]=section}
 const move=(name,id)=>{const element=typeof id==='string'?el(id):id;if(element)pages[name].append(element)};
 move('home',root.querySelector('.bento-grid'));move('learning','cfo-learning');
for(const id of ['cfo-daily-briefing','cfo-home-pulse','cfo-home-calendar','cfo-home-goals','cfo-home-actions'])move('home',id);
 for(const id of ['cfo-analysis-periods','cfo-food-budget','cfo-insights','cfo-category-budget-panel'])move('analytics',id);
 move('sources','cfo-data-details');el('cfo-data-details').open=true;
 for(const id of ['cfo-profile-details','cfo-delivery']){move('settings',id);el(id).open=true}
 for(const child of [...root.children]){if(child.tagName==='P'&&child.id!=='cfo-status')pages.learning.append(child)}
 move('goals','cfo-goals-details');move('assistant','cfo-chat');move('assistant','cfo-ai-settings');move('operations','cfo-operations-details');
 el('cfo-operations-details').insertBefore(el('cfo-ai-proposal'),el('cfo-history-filters'));
 const reference=document.querySelector('.sidebar button[data-nav="assistant"]');const goals=node('button','Цели');goals.dataset.nav='goals';goals.type='button';reference.parentElement.insertBefore(goals,reference);
 for(const button of document.querySelectorAll('.sidebar button[data-nav]')){const name=button.dataset.nav;if(!screenNames[name]){button.hidden=true;continue}button.onclick=null;button.addEventListener('click',event=>{event.preventDefault();event.stopImmediatePropagation();setScreen(name)},true)}
 window.addEventListener('popstate',()=>setScreen(new URLSearchParams(location.search).get('screen')||'home',false));
 for(const id of ['cfo-profile','cfo-delivery-settings'])el(id).addEventListener('input',()=>el(id).dataset.dirty='1');
 setScreen(new URLSearchParams(location.search).get('screen')||'home',false);
}
function panel(title){const card=node('article');card.className='cfo-panel';card.append(node('h3',title));return card}
function openButton(label,screen){const b=node('button',label);b.type='button';b.onclick=()=>setScreen(screen);return b}
function renderHome(d,a){
 const pulse=el('cfo-home-pulse');pulse.replaceChildren();const p=d.financial_position;
 for(const [label,value] of [['Расходы сегодня · известно',a.periods.today.expenses],['Расходы месяца · известно',a.periods.month.expenses],['Доходы месяца · известно',a.periods.month.income],['Неприкосновенный резерв',p.reserve],['Прочие защищённые средства',p.protected]]){const card=panel(label);card.classList.add('cfo-mini-metric');card.append(node('strong',rub(value)));if(value===null)card.append(node('p','Нужно значение владельца; неизвестное не равно нулю.'));pulse.append(card)}
 const calendar=el('cfo-home-calendar');calendar.replaceChildren();const income=panel('Подтверждённое поступление');const confirmed=a.calendar.next_confirmed_income;income.append(node('p',confirmed?confirmed.name+' · '+confirmed.date+' · '+rub(confirmed.amount):'Не задано.'));
 for(const expected of a.calendar.expected_incomes)income.append(node('small','Ожидается, не гарантировано: '+expected.name+' · '+expected.date+' · '+rub(expected.amount)));
 if(a.calendar.undated_incomes.length)income.append(node('p','Без даты: '+a.calendar.undated_incomes.join(', ')+'. В расчёт обещанного поступления не включено.'));calendar.append(income);
 const obligations=panel('Ближайшие обязательства');if(!a.calendar.obligations_complete)obligations.append(node('p','Перечень обязательных расходов не подтверждён полностью. Свободная сумма остаётся неизвестной.'));
 for(const item of a.calendar.upcoming_obligations.slice(0,4))obligations.append(node('p',item.date+' · '+item.name+' · '+rub(item.amount)+' · '+(item.certainty==='confirmed'?'подтверждено':'оценка')));
 if(a.calendar.obligations_complete&&!a.calendar.upcoming_obligations.length)obligations.append(node('p','В подтверждённом календаре на 30 дней записей нет.'));obligations.append(openButton('Настроить профиль','settings'));calendar.append(obligations);
 const goals=el('cfo-home-goals');goals.replaceChildren(node('h3','Ваши накопления'));if(!p.goals.length)goals.append(node('p','Цель пока не задана. Укажите сумму и срок, чтобы рассчитать взносы.'));
 for(const goal of p.goals.slice(0,3))goals.append(node('p',goal.name+' · '+rub(goal.current_amount)+' из '+rub(goal.target_amount)));goals.append(openButton('Открыть цели','goals'));
 const actions=el('cfo-home-actions');actions.replaceChildren(node('h3','Что стоит проверить'));
 if(p.missing.length)actions.append(node('p','Для безопасной суммы не хватает: '+p.missing.join('; ')),openButton('Дополнить данные','settings'));
 if(p.reserve!==null&&Number(p.reserve)===0)actions.append(node('p','Резерв задан 0 ₽. Запаса на неожиданные расходы нет; настройки не менялись.'));
 for(const item of d.patterns.filter(v=>v.kind==='unusual_expense_candidate').slice(0,3))actions.append(node('p','Кандидат необычной траты: '+rub(item.amount)+' · '+(names[item.category]||item.category)+' · #'+item.transaction_id+'. Требует проверки.'));
 actions.append(openButton('Проверить операции','operations'));
}
function renderAnalysis(d,a){
 const root=el('cfo-analysis-periods');root.replaceChildren(node('h3','Периоды: что изменилось в известных данных'));const content=node('div');table(content,['Период','Расходы','Поступления','Неясных назначений'],[['Сегодня','today'],['Последние 7 дней','week'],['Предыдущие 7 дней','prior_week'],['Текущий месяц','month'],['Прошлый месяц','previous_month']].map(([label,key])=>[label,rub(a.periods[key].expenses),rub(a.periods[key].income),String(a.periods[key].unresolved_count)]));root.append(content,node('p',a.comparison+' Разность расходов за недели: '+rub(a.week_expense_delta)+'. Причины и полнота не доказаны.'));
 const food=el('cfo-food-budget'),f=a.food;food.replaceChildren(node('h3','Питание: известные траты и ваш лимит'),node('p','Месяц: '+rub(f.month_spent)+' · среднее за календарный день '+rub(f.daily_known_average)),node('p',f.limit===null?'Лимит питания не задан. Допустимую сумму не выдумываю.':'Остаток лимита '+rub(f.remaining)+' на '+f.remaining_days+' дней · верхняя граница на день '+rub(f.daily_budget)),node('p',f.notice));
}
async function loadLearning(){
 const data=await call('/learning');el('cfo-learning-status').textContent='Подтверждено '+data.confirmed+' · отозвано '+data.withdrawn+' · допустимо '+data.eligible+'. '+(data.eligible<20?'Меток мало, точность не измерена.':'Нужна независимая оценка.')+' Автопродвижение выключено.';
 const result=await call('/clusters');const root=el('cfo-clusters');root.replaceChildren(node('h3','Группы для проверки'));if(!result.clusters.length)root.append(node('p','Повторяющихся групп в ограниченной выборке не найдено.'));
 for(const group of result.clusters){const card=panel(group.common_features.name_fold+' · '+group.size+' операций');card.append(node('p',group.contradictions?'Подтверждения противоречат друг другу.':group.suggested_category?'Кандидат: '+(names[group.suggested_category]||group.suggested_category):'Категория неизвестна.'));for(const example of group.examples.slice(0,4))card.append(node('p','#'+example.id+' · '+example.merchant+' · '+(names[example.category]||example.category)));root.append(card)}
}
