for(const q of ['Сколько можно безопасно потратить?','Что изменилось за неделю?','Сколько трачу на питание?','Какие подписки у меня есть?','Что будет, если я потрачу 5000 рублей?','Чему ты научился?']){const b=node('button',q);b.type='button';b.onclick=()=>{el('cfo-question').elements.namedItem('message').value=q;el('cfo-question').requestSubmit()};el('cfo-quick-questions').append(b)}
run(async()=>{try{await load()}finally{el('personal-cfo').classList.add('cfo-ready')}});run(loadRuntime);setInterval(()=>{if(!document.hidden)loadRuntime().catch(()=>{el('cfo-runtime-status').textContent='Не удалось обновить состояние; показаны прежние данные.'})},60000);

