let importPreview=null;
function updateImportConsent(){
 if(!importPreview)return;
 const verdict=importPreview.validation?.verdict||'review';
 const count=Number(importPreview.new||0)+(el('cfo-import-include-possible').checked?Number(importPreview.possible_duplicate||0):0);
 el('cfo-import-apply').disabled=verdict==='unsafe'||count===0||(verdict==='review'&&!el('cfo-import-ack').checked)||(Number(importPreview.possible_duplicate||0)>0&&(!el('cfo-import-include-possible').checked||el('cfo-import-dup-wrap').hidden));
 el('cfo-import-apply').textContent=verdict==='unsafe'?'Импорт заблокирован проверкой':(el('cfo-import-include-possible').checked?'Импортировать подтверждённые операции':'Импортировать новые');
}

function importError(err){const message=String(err&&err.message||'');return /fetch|network|load failed|timeout|aborted/i.test(message)?'Сервис не ответил или обработка заняла слишком много времени. Проверьте, что JARVIS запущен, и повторите.':(message||'Не удалось выполнить действие. Повторите позже.')}
async function previewImportFile(form){
 const button=form.querySelector('button'),status=el('cfo-import-status');button.disabled=true;importPreview=null;el('cfo-import-ack').checked=false;el('cfo-import-include-possible').checked=false;el('cfo-import-dup-wrap').hidden=true;el('cfo-import-apply').hidden=true;status.textContent='Читаем выписку…';
 try{const fd=new FormData(form);const r=await fetch('/api/cfo/import/preview',{method:'POST',headers:{'x-review-token':TOKEN},body:fd});const d=await readResponse(r);importPreview=d;const v=d.validation||{};const verdict=v.verdict||'review';const label={safe:'пройдена',review:'частичная',unsafe:'не пройдена'}[verdict]||verdict;status.textContent='Новых: '+d.new+' · дублей: '+d.duplicate+' · сомнительных: '+d.possible_duplicate+'. Импорт не применён.';const notes=[];if(v.parsed_rows!==undefined)notes.push('Распознано строк: '+v.parsed_rows+(v.independent_operation_lines!==null&&v.independent_operation_lines!==undefined?' · независимо найдено: '+v.independent_operation_lines:''));if(v.period&&v.period.from)notes.push('Период операций: '+v.period.from+' — '+v.period.to);if(v.document_controls?.document_period)notes.push('Окно выписки: '+v.document_controls.document_period.from+' — '+v.document_controls.document_period.to+(v.document_controls.signed_order_basis==='processing_date'?' · по датам обработки':''));if(v.account_suffix)notes.push('Маскированный номер из документа: ****'+v.account_suffix);if(d.account_identity&&!d.account_identity.reconciled)notes.push('Связь метки источника с банковским счётом не подтверждена: сверьте её перед импортом');if(v.balance_check)notes.push(v.balance_check.available?'Сверка баланса: проверено '+v.balance_check.checked+', расхождений '+v.balance_check.mismatch:'Сверка баланса недоступна в этом PDF');if(v.kinds&&v.kinds.net!==undefined&&v.kinds.net!==null)notes.push('Итог по операциям: '+(v.kinds.currency==='RUB'?rub(v.kinds.net):String(v.kinds.net)+' '+(v.kinds.currency||'валюта неизвестна')));else if(v.kinds?.by_currency&&Object.keys(v.kinds.by_currency).length>1)notes.push('Разные валюты: общий денежный итог не рассчитывается');if(v.unsafe_reasons&&v.unsafe_reasons.length)notes.push('Причины: '+v.unsafe_reasons.map(reason=>({existing_identity_conflict:'ID операции конфликтует с датой, валютой или суммой в истории',source_identity_conflict:'ID внутри выписки связан с разными денежными данными',document_control_mismatch:'Не подтверждены контрольные итоги или последовательность остатков; сверьте исходную выписку',savings_signed_row_mismatch:'Суммы или направления не совпали с документом',savings_unparsed_rows:'Не все строки сберегательной выписки проверены',savings_duplicate_reference:'Повторилась банковская ссылка операции',savings_balance_mismatch:'Остатки сберегательной выписки не сходятся',savings_outside_coverage:'Есть операции вне проверенного периода',savings_currency_unverified:'Валюта выписки не подтверждена',savings_window_mismatch:'Период выписки не совпадает с датами контрольных остатков'}[reason]||reason)).join(', '));notes.push('Проверка: '+label+'. '+(v.notice||''));el('cfo-import-validation').textContent=notes.join(' · ');el('cfo-import-ack-wrap').hidden=verdict!=='review';el('cfo-import-apply').hidden=false;el('cfo-import-dup-wrap').hidden=!d.possible_duplicate||!Array.isArray(d.possible_rows)||d.possible_duplicate>200;updateImportConsent();el('cfo-import-apply').textContent=verdict==='unsafe'?'Импорт заблокирован проверкой':'Импортировать новые';table(el('cfo-import-preview'),['Статус','Дата','Сумма','Магазин','Описание'],[...d.rows.slice(0,200).map(x=>['Новая',x.tx_date,x.currency==='RUB'?rub(x.amount):String(x.amount)+' '+(x.currency||'валюта неизвестна'),x.merchant,x.description]),...(d.possible_rows||[]).slice(0,200).map(x=>['Похожая: нужна сверка',x.tx_date,x.currency==='RUB'?rub(x.amount):String(x.amount)+' '+(x.currency||'валюта неизвестна'),x.merchant,x.description])]);if(d.possible_duplicate>200)status.textContent+=' Более 200 похожих строк: разделите выписку для отдельной сверки.';if(d.rows.length>200)status.textContent+=' Показаны первые 200 из '+d.rows.length+'.';if(d.warnings.length)status.textContent+=' Предупреждения: '+d.warnings.join('; ')}
 catch(err){status.textContent=importError(err);el('cfo-import-apply').hidden=true}finally{button.disabled=false}
}
