if(!WEB_ONLY) el('cfo-import-apply').onclick=()=>run(async()=>{if(!importPreview)return;const button=el('cfo-import-apply'),status=el('cfo-import-status');button.disabled=true;try{const d=await call('/import/apply','POST',{preview_id:importPreview.preview_id,owner_confirmed:true,include_possible_duplicates:el('cfo-import-include-possible').checked,acknowledge_validation:el('cfo-import-ack').checked});status.textContent='Импортировано операций: '+d.inserted+'. Обновляю данные…';importPreview=null;button.hidden=true;await load();el('cfo-group-load').click()}catch(err){status.textContent=importError(err)}finally{button.disabled=false}});

